-- GlaukOS: ship history for the demo + removal of the test accounts.
-- Safe to run twice (on conflict do nothing).
begin;

-- 1. test data from the end-to-end checks
delete from public.events where actor_id in (select id from public.crew where name ilike 'test\_%');
delete from public.events where actor like '%:test\_%';
delete from auth.users where id in (select id from public.crew where name ilike 'test\_%');

-- 2. 64 reports, 400 events over the last 22 hours
on conflict (event_id) do nothing;

commit;

select department, count(distinct report_id) as reports from public.events where device = 'seed' group by department order by 1;
